"use strict";(globalThis.webpackChunkaarati_sangrah=globalThis.webpackChunkaarati_sangrah||[]).push([[6023],{32397(a,t,e){e.r(t),e.d(t,{assets:()=>h,contentTitle:()=>o,default:()=>c,frontMatter:()=>i,metadata:()=>r,toc:()=>u});const r=JSON.parse('{"id":"shastrarth/Jestha-Gauri-mahalaxmi/day-2","title":"\u0917\u094c\u0930\u0940\u092a\u0942\u091c\u0928 (\u0926\u093f\u0935\u0938 \u0926\u0941\u0938\u0930\u093e)","description":"\u0926\u0941\u0938\u0930\u094d\u092f\u093e \u0926\u093f\u0935\u0936\u0940 \u092e\u094d\u0939\u0923\u091c\u0947\u091a \u091c\u094d\u092f\u0947\u0937\u094d\u0920\u093e \u0928\u0915\u094d\u0937\u0924\u094d\u0930\u093e\u0935\u0930 \u0917\u094c\u0930\u0940\u0902\u091a\u0940 \u092a\u0942\u091c\u093e \u0915\u0947\u0932\u0940 \u091c\u093e\u0924\u0947. \u0938\u0915\u093e\u0933\u0940 \u0917\u094c\u0930\u0940\u0902\u091a\u0940/\u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0940 \u092a\u0942\u091c\u093e-\u0906\u0930\u0924\u0940 \u0915\u0930\u0942\u0928 \u0915\u0947\u0932\u0947\u0932\u094d\u092f\u093e \u092b\u0930\u093e\u0933\u093e\u091a\u093e (\u0930\u0935\u094d\u092f\u093e\u091a\u093e \u0932\u093e\u0921\u0942, \u092c\u0947\u0938\u0928\u0932\u093e\u0921\u0942, \u0915\u0930\u0902\u091c\u0940, \u091a\u0915\u0932\u0940, \u0936\u0947\u0935, \u0917\u0941\u0933\u092a\u093e\u092a\u0921\u0940\u091a\u093e \u0932\u093e\u0921\u0942) \u0928\u0948\u0935\u0947\u0926\u094d\u092f \u0926\u093e\u0916\u0935\u0924\u093e\u0924. \u0928\u0902\u0924\u0930 \u0938\u0902\u0927\u094d\u092f\u093e\u0915\u093e\u0933\u0940 \u0906\u0930\u0924\u0940 \u0915\u0930\u0924\u093e\u0924. \u092a\u0941\u0930\u0923\u092a\u094b\u0933\u0940, \u091c\u094d\u0935\u093e\u0930\u0940\u091a\u094d\u092f\u093e \u092a\u093f\u0920\u093e\u091a\u0940 \u0906\u0902\u092c\u0940\u0932, \u0906\u0902\u092c\u093e\u0921\u0940\u091a\u0940 \u092d\u093e\u091c\u0940, \u0938\u094b\u0933\u093e \u092d\u093e\u091c\u094d\u092f\u093e\u0902\u091a\u0940 \u090f\u0915\u0924\u094d\u0930 \u092d\u093e\u091c\u0940, \u0926\u093f\u0935\u0947\u092b\u0933 \u0935\u0917\u0948\u0930\u0947 \u092a\u0926\u093e\u0930\u094d\u0925\u093e\u0902\u091a\u093e \u0928\u0948\u0935\u0947\u0926\u094d\u092f\u093e\u0924 \u0938\u092e\u093e\u0935\u0947\u0936 \u0905\u0938\u0924\u094b. \u0928\u0948\u0935\u0947\u0926\u094d\u092f\u093e\u0924 \u0936\u0947\u0902\u0917\u0926\u093e\u0923\u093e \u0906\u0923\u093f \u0921\u093e\u0933\u0940\u091a\u0940 \u091a\u091f\u0923\u0940, \u092a\u0902\u091a\u093e\u092e\u0943\u0924, \u092a\u0921\u0935\u0933 \u0918\u093e\u0932\u0942\u0928 \u0915\u0947\u0932\u0947\u0932\u0940 \u0924\u093e\u0915\u093e\u091a\u0940 \u0915\u0922\u0940, \u0915\u091f\u093e\u091a\u0940 \u0906\u092e\u091f\u0940, \u0935\u0947\u0917\u0935\u0947\u0917\u0933\u094d\u092f\u093e \u092a\u094d\u0930\u0915\u093e\u0930\u091a\u0940 \u092d\u091c\u0940, \u092a\u093e\u092a\u0921, \u0932\u094b\u0923\u091a\u0947 \u0907\u0924\u094d\u092f\u093e\u0926\u0940. \u0915\u0947\u0932\u0947\u0932\u0947 \u0938\u0930\u094d\u0935 \u092a\u0926\u093e\u0930\u094d\u0925 \u0915\u0947\u0933\u0940\u091a\u094d\u092f\u093e \u092a\u093e\u0928\u093e\u0935\u0930 \u0920\u0947\u0935\u0924\u093e\u0924. \u092e\u0939\u093e\u0930\u093e\u0937\u094d\u091f\u094d\u0930\u093e\u0924 \u0938\u093e\u092f\u0902\u0915\u093e\u0933\u0940 \u092e\u0939\u093f\u0932\u093e\u0902\u091a\u093e \u0939\u0933\u0926\u0940\u0915\u0941\u0902\u0915\u0942 \u0915\u093e\u0930\u094d\u092f\u0915\u094d\u0930\u092e \u0915\u0947\u0932\u093e \u091c\u093e\u0924\u094b. \u0926\u0930\u094d\u0936\u0928\u093e\u0932\u093e \u0906\u0932\u0947\u0932\u094d\u092f\u093e \u092e\u0939\u093f\u0932\u093e \u0935 \u092e\u0941\u0932\u0940\u0902\u091a\u0947 \u0906\u0926\u0930\u092a\u0942\u0930\u094d\u0935\u0915 \u0938\u094d\u0935\u093e\u0917\u0924 \u0915\u0930\u0923\u094d\u092f\u093e\u091a\u0940 \u092a\u0926\u094d\u0927\u0924\u0940 \u092a\u094d\u0930\u091a\u0932\u093f\u0924 \u0906\u0939\u0947.   \u0935\u093f\u0926\u0930\u094d\u092d\u093e\u0924\u0932\u094d\u092f\u093e \u0917\u094c\u0930\u0940\u0902\u091a\u093e (\u0932\u0915\u094d\u0937\u094d\u092e\u094d\u092f\u093e\u0902\u091a\u093e) \u0928\u0948\u0935\u0947\u0926\u094d\u092f\u0939\u0940 \u0935\u0939\u0931\u094d\u0939\u093e\u0921\u0940 \u0905\u0918\u0933\u092a\u0918\u0933 \u092a\u094d\u0930\u0935\u0943\u0924\u094d\u0924\u0940\u0938\u093e\u0930\u0916\u093e\u091a! \u091c\u094b\u0902\u0927\u0933\u094d\u092f\u093e\u091a\u0940 \u0906\u0902\u092c\u0940\u0932 \u0939\u0935\u0940\u091a! \u092c\u0939\u0941\u0927\u093e \u0917\u094b\u0921. \u0915\u0927\u0940 \u0924\u093f\u0916\u091f-\u0916\u093e\u0930\u0940. \u0924\u0940\u0939\u0940 \u0938\u0924\u094d\u092f\u0928\u093e\u0930\u093e\u092f\u0923\u093e\u091a\u094d\u092f\u093e \u092a\u094d\u0930\u0938\u093e\u0926\u093e\u0938\u093e\u0930\u0916\u0940 \u0938\u0935\u094d\u0935\u093e \u092a\u091f\u0940\u0924! \u0938\u0935\u094d\u0935\u093e \u092a\u093e\u0935\u0936\u0947\u0930/\u0936\u0947\u0930/\u092a\u093e\u092f\u0932\u0940! \u0906\u0902\u092c\u0940\u0932 \u0936\u093f\u091c\u0935\u0932\u0947\u0932\u0902 \u092e\u094b\u0920\u0902 \u092a\u093e\u0924\u0947\u0932\u0902 \u0924\u0938\u0902\u091a \u0932\u0915\u094d\u0937\u094d\u092e\u094d\u092f\u093e\u0902\u092a\u0941\u0922\u0947! \u092e\u0917 \u092a\u0941\u0930\u0923\u092a\u094b\u0933\u0940, \u0967\u096c \u092d\u093e\u091c\u094d\u092f\u093e \u0935\u0917\u0948\u0930\u0947 \u0906\u0939\u0947\u091a! \u091c\u0947\u0935\u093e\u092f\u0932\u093e \u0916\u0942\u092a \u0932\u094b\u0915\u093e\u0902\u0928\u093e \u092c\u094b\u0932\u0935\u093e\u092f\u091a\u0902. \u0906\u0902\u092c\u093f\u0932\u0940\u091a\u0947 \u092a\u093e\u0935\u093f\u0924\u094d\u0930\u094d\u092f \u092e\u094b\u0920\u0947. \u0907\u0925\u0947 \u0924\u093f\u0925\u0947 \u0939\u093e\u0924 \u0927\u0941\u0935\u093e\u092f\u091a\u093e \u0928\u093e\u0939\u0940- \u0905\u0902\u0917\u0923\u093e\u0924 \u090f\u0915\u093e \u0916\u093e\u0938 \u0916\u0921\u094d\u0921\u094d\u092f\u093e\u0924\u091a \u0939\u093e\u0924 \u0927\u0941\u0935\u093e\u092f\u091a\u0947! \'\u0938\u092e\u0941\u0926\u094d\u0930\' \u092e\u094d\u0939\u0923\u0924\u093e\u0924 \u0924\u094d\u092f\u093e\u0932\u093e. \u0928\u0902\u0924\u0930 \u0924\u094b \u0916\u0921\u094d\u0921\u093e \u092c\u0941\u091c\u0935\u093e\u092f\u091a\u093e! \u0939\u0933\u0926\u0940-\u0915\u0941\u0902\u0915\u0935\u093e\u0932\u093e \u092f\u0947\u0923\u093e\u0930\u0940 \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915\u091c\u0923 \u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0940 \u0916\u0923\u093e-\u0928\u093e\u0930\u0933\u093e\u0902\u091a\u0940 \u0913\u091f\u0940 \u0906\u0923\u093f \u0910\u092a\u0924\u0940\u0928\u0941\u0938\u093e\u0930 \u0927\u093e\u0928\u094d\u092f \u0918\u0947\u090a\u0928 \u092f\u0947\u0923\u093e\u0930! \u092a\u0941\u0928\u094d\u0939\u093e \u0917\u0943\u0939\u093f\u0923\u0940\u0928\u0947 \u0924\u0940 \u0938\u0917\u0933\u0940 \'\u0930\u093e\u0938\' \u0918\u091f\u0938\u094d\u0925\u093e\u092a\u0928\u0947\u092a\u0942\u0930\u094d\u0935\u0940 \u0918\u0930\u093e\u0924\u091a \u092a\u0948-\u092a\u093e\u0939\u0941\u0923\u094d\u092f\u093e\u0902\u0938\u093e\u0920\u0940 \u092a\u0926\u093e\u0930\u094d\u0925 \u0916\u093e\u090a \u0918\u093e\u0932\u0942\u0928\u091a \u0938\u0902\u092a\u0935\u093e\u092f\u091a\u0940. \u0909\u091a\u0932\u0942\u0928 \u0918\u0930\u093e\u092c\u093e\u0939\u0947\u0930 \u0915\u093e\u0939\u0940 \u0928\u094d\u092f\u093e\u092f\u091a\u0902 \u0928\u093e\u0939\u0940. \u0905\u0928\u0947\u0915 \u0920\u093f\u0915\u093e\u0923\u0940 \u0928\u0948\u0935\u0947\u0926\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u0935\u0947\u0933\u0940 \u0915\u0923\u0915\u0947\u091a\u0947 \u0967\u096c, \u0915\u0941\u0920\u0947 \u0969\u0968 \u0926\u093f\u0935\u0947 \u0906\u0923\u093f \u092e\u0941\u0920\u0947 \u0915\u0930\u0942\u0928 \u0915\u0947\u0933\u0940\u091a\u094d\u092f\u093e \u092a\u093e\u0928\u093e\u092d\u094b\u0935\u0924\u0940 \u0920\u0947\u0935\u093e\u092f\u091a\u0947! \u0928\u0948\u0935\u0947\u0926\u094d\u092f \u0915\u0947\u0933\u0940\u091a\u094d\u092f\u093e \u092a\u093e\u0928\u093e\u0935\u0930\u091a \u0935\u093e\u0922\u093e\u092f\u091a\u093e. \u0935\u093e\u0922\u0942\u0928 \u091d\u093e\u0932\u0902 \u0915\u0940 \u0935\u0931\u094d\u0939\u093e\u0921\u093e\u0924 \u0924\u094d\u092f\u093e \u0916\u094b\u0932\u0940\u091a\u0902 \u0926\u093e\u0930 \u0915\u093e\u0939\u0940 \u0915\u093e\u0933 \u092c\u0902\u0926 \u0920\u0947\u0935\u0924\u093e\u0924. \u0906\u0924 \u0932\u0915\u094d\u0937\u094d\u092e\u094d\u092f\u093e \u091c\u0947\u0935\u0924\u093e\u0924 \u0928\u093e! \u0926\u093e\u0930 \u0909\u0918\u0921\u0932\u0902 \u0915\u0940 \u092c\u093e\u0930\u0915\u093e\u0908\u0928\u0902 \u092a\u093e\u0928 \u092c\u0918\u093e\u092f\u091a\u0902. \u0915\u094b\u0923\u0915\u094b\u0923\u0924\u0947 \u092a\u0926\u093e\u0930\u094d\u0925 \u0909\u0937\u094d\u091f\u093e\u0935\u0932\u0947 \u0917\u0947\u0932\u0947\u0924? \u090f\u0915 \u0938\u0902\u0915\u0947\u0924 \u092e\u093e\u0924\u094d\u0930 \u0938\u0917\u0933\u0940\u0915\u0921\u0947! \u0917\u094c\u0930\u0940, \u0932\u0915\u094d\u0937\u094d\u092e\u0940 \u0918\u0930\u093e\u0924 \u0905\u0938\u0947\u092a\u0930\u094d\u092f\u0902\u0924 \u0918\u0930\u093e\u0924\u0932\u093e \u092a\u0948\u0938\u093e \u092c\u093e\u0939\u0947\u0930 \u0926\u094d\u092f\u093e\u092f\u091a\u093e \u0928\u093e\u0939\u0940.","source":"@site/docs/shastrarth/Jestha-Gauri-mahalaxmi/3-day-2.md","sourceDirName":"shastrarth/Jestha-Gauri-mahalaxmi","slug":"/jestha-gauri-mahalaxmi-day-2","permalink":"/jestha-gauri-mahalaxmi-day-2","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"slug":"/jestha-gauri-mahalaxmi-day-2"},"sidebar":"tutorialSidebar","previous":{"title":"\u0917\u094c\u0930\u0940 \u0906\u0935\u093e\u0939\u0928 (\u0926\u093f\u0935\u0938 \u092a\u0939\u093f\u0932\u093e)","permalink":"/jestha-gauri-mahalaxmi-day-1"},"next":{"title":"\u0935\u093f\u0938\u0930\u094d\u091c\u0928 (\u0926\u093f\u0935\u0938 \u0924\u093f\u0938\u0930\u093e)","permalink":"/jestha-gauri-mahalaxmi-day-3"}}');var n=e(74848),s=e(28453);const i={slug:"/jestha-gauri-mahalaxmi-day-2"},o="\u0917\u094c\u0930\u0940\u092a\u0942\u091c\u0928 (\u0926\u093f\u0935\u0938 \u0926\u0941\u0938\u0930\u093e)",h={},u=[];function l(a){const t={br:"br",h1:"h1",header:"header",p:"p",...(0,s.R)(),...a.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"\u0917\u094c\u0930\u0940\u092a\u0942\u091c\u0928-\u0926\u093f\u0935\u0938-\u0926\u0941\u0938\u0930\u093e",children:"\u0917\u094c\u0930\u0940\u092a\u0942\u091c\u0928 (\u0926\u093f\u0935\u0938 \u0926\u0941\u0938\u0930\u093e)"})}),"\n",(0,n.jsxs)(t.p,{children:["\u0926\u0941\u0938\u0930\u094d\u092f\u093e \u0926\u093f\u0935\u0936\u0940 \u092e\u094d\u0939\u0923\u091c\u0947\u091a \u091c\u094d\u092f\u0947\u0937\u094d\u0920\u093e \u0928\u0915\u094d\u0937\u0924\u094d\u0930\u093e\u0935\u0930 \u0917\u094c\u0930\u0940\u0902\u091a\u0940 \u092a\u0942\u091c\u093e \u0915\u0947\u0932\u0940 \u091c\u093e\u0924\u0947. \u0938\u0915\u093e\u0933\u0940 \u0917\u094c\u0930\u0940\u0902\u091a\u0940/\u092e\u0939\u093e\u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0940 \u092a\u0942\u091c\u093e-\u0906\u0930\u0924\u0940 \u0915\u0930\u0942\u0928 \u0915\u0947\u0932\u0947\u0932\u094d\u092f\u093e \u092b\u0930\u093e\u0933\u093e\u091a\u093e (\u0930\u0935\u094d\u092f\u093e\u091a\u093e \u0932\u093e\u0921\u0942, \u092c\u0947\u0938\u0928\u0932\u093e\u0921\u0942, \u0915\u0930\u0902\u091c\u0940, \u091a\u0915\u0932\u0940, \u0936\u0947\u0935, \u0917\u0941\u0933\u092a\u093e\u092a\u0921\u0940\u091a\u093e \u0932\u093e\u0921\u0942) \u0928\u0948\u0935\u0947\u0926\u094d\u092f \u0926\u093e\u0916\u0935\u0924\u093e\u0924. \u0928\u0902\u0924\u0930 \u0938\u0902\u0927\u094d\u092f\u093e\u0915\u093e\u0933\u0940 \u0906\u0930\u0924\u0940 \u0915\u0930\u0924\u093e\u0924. \u092a\u0941\u0930\u0923\u092a\u094b\u0933\u0940, \u091c\u094d\u0935\u093e\u0930\u0940\u091a\u094d\u092f\u093e \u092a\u093f\u0920\u093e\u091a\u0940 \u0906\u0902\u092c\u0940\u0932, \u0906\u0902\u092c\u093e\u0921\u0940\u091a\u0940 \u092d\u093e\u091c\u0940, \u0938\u094b\u0933\u093e \u092d\u093e\u091c\u094d\u092f\u093e\u0902\u091a\u0940 \u090f\u0915\u0924\u094d\u0930 \u092d\u093e\u091c\u0940, \u0926\u093f\u0935\u0947\u092b\u0933 \u0935\u0917\u0948\u0930\u0947 \u092a\u0926\u093e\u0930\u094d\u0925\u093e\u0902\u091a\u093e \u0928\u0948\u0935\u0947\u0926\u094d\u092f\u093e\u0924 \u0938\u092e\u093e\u0935\u0947\u0936 \u0905\u0938\u0924\u094b. \u0928\u0948\u0935\u0947\u0926\u094d\u092f\u093e\u0924 \u0936\u0947\u0902\u0917\u0926\u093e\u0923\u093e \u0906\u0923\u093f \u0921\u093e\u0933\u0940\u091a\u0940 \u091a\u091f\u0923\u0940, \u092a\u0902\u091a\u093e\u092e\u0943\u0924, \u092a\u0921\u0935\u0933 \u0918\u093e\u0932\u0942\u0928 \u0915\u0947\u0932\u0947\u0932\u0940 \u0924\u093e\u0915\u093e\u091a\u0940 \u0915\u0922\u0940, \u0915\u091f\u093e\u091a\u0940 \u0906\u092e\u091f\u0940, \u0935\u0947\u0917\u0935\u0947\u0917\u0933\u094d\u092f\u093e \u092a\u094d\u0930\u0915\u093e\u0930\u091a\u0940 \u092d\u091c\u0940, \u092a\u093e\u092a\u0921, \u0932\u094b\u0923\u091a\u0947 \u0907\u0924\u094d\u092f\u093e\u0926\u0940. \u0915\u0947\u0932\u0947\u0932\u0947 \u0938\u0930\u094d\u0935 \u092a\u0926\u093e\u0930\u094d\u0925 \u0915\u0947\u0933\u0940\u091a\u094d\u092f\u093e \u092a\u093e\u0928\u093e\u0935\u0930 \u0920\u0947\u0935\u0924\u093e\u0924. \u092e\u0939\u093e\u0930\u093e\u0937\u094d\u091f\u094d\u0930\u093e\u0924 \u0938\u093e\u092f\u0902\u0915\u093e\u0933\u0940 \u092e\u0939\u093f\u0932\u093e\u0902\u091a\u093e \u0939\u0933\u0926\u0940\u0915\u0941\u0902\u0915\u0942 \u0915\u093e\u0930\u094d\u092f\u0915\u094d\u0930\u092e \u0915\u0947\u0932\u093e \u091c\u093e\u0924\u094b. \u0926\u0930\u094d\u0936\u0928\u093e\u0932\u093e \u0906\u0932\u0947\u0932\u094d\u092f\u093e \u092e\u0939\u093f\u0932\u093e \u0935 \u092e\u0941\u0932\u0940\u0902\u091a\u0947 \u0906\u0926\u0930\u092a\u0942\u0930\u094d\u0935\u0915 \u0938\u094d\u0935\u093e\u0917\u0924 \u0915\u0930\u0923\u094d\u092f\u093e\u091a\u0940 \u092a\u0926\u094d\u0927\u0924\u0940 \u092a\u094d\u0930\u091a\u0932\u093f\u0924 \u0906\u0939\u0947.   \u0935\u093f\u0926\u0930\u094d\u092d\u093e\u0924\u0932\u094d\u092f\u093e \u0917\u094c\u0930\u0940\u0902\u091a\u093e (\u0932\u0915\u094d\u0937\u094d\u092e\u094d\u092f\u093e\u0902\u091a\u093e) \u0928\u0948\u0935\u0947\u0926\u094d\u092f\u0939\u0940 \u0935\u0939\u0931\u094d\u0939\u093e\u0921\u0940 \u0905\u0918\u0933\u092a\u0918\u0933 \u092a\u094d\u0930\u0935\u0943\u0924\u094d\u0924\u0940\u0938\u093e\u0930\u0916\u093e\u091a! \u091c\u094b\u0902\u0927\u0933\u094d\u092f\u093e\u091a\u0940 \u0906\u0902\u092c\u0940\u0932 \u0939\u0935\u0940\u091a! \u092c\u0939\u0941\u0927\u093e \u0917\u094b\u0921. \u0915\u0927\u0940 \u0924\u093f\u0916\u091f-\u0916\u093e\u0930\u0940. \u0924\u0940\u0939\u0940 \u0938\u0924\u094d\u092f\u0928\u093e\u0930\u093e\u092f\u0923\u093e\u091a\u094d\u092f\u093e \u092a\u094d\u0930\u0938\u093e\u0926\u093e\u0938\u093e\u0930\u0916\u0940 \u0938\u0935\u094d\u0935\u093e \u092a\u091f\u0940\u0924! \u0938\u0935\u094d\u0935\u093e \u092a\u093e\u0935\u0936\u0947\u0930/\u0936\u0947\u0930/\u092a\u093e\u092f\u0932\u0940! \u0906\u0902\u092c\u0940\u0932 \u0936\u093f\u091c\u0935\u0932\u0947\u0932\u0902 \u092e\u094b\u0920\u0902 \u092a\u093e\u0924\u0947\u0932\u0902 \u0924\u0938\u0902\u091a \u0932\u0915\u094d\u0937\u094d\u092e\u094d\u092f\u093e\u0902\u092a\u0941\u0922\u0947! \u092e\u0917 \u092a\u0941\u0930\u0923\u092a\u094b\u0933\u0940, \u0967\u096c \u092d\u093e\u091c\u094d\u092f\u093e \u0935\u0917\u0948\u0930\u0947 \u0906\u0939\u0947\u091a! \u091c\u0947\u0935\u093e\u092f\u0932\u093e \u0916\u0942\u092a \u0932\u094b\u0915\u093e\u0902\u0928\u093e \u092c\u094b\u0932\u0935\u093e\u092f\u091a\u0902. \u0906\u0902\u092c\u093f\u0932\u0940\u091a\u0947 \u092a\u093e\u0935\u093f\u0924\u094d\u0930\u094d\u092f \u092e\u094b\u0920\u0947. \u0907\u0925\u0947 \u0924\u093f\u0925\u0947 \u0939\u093e\u0924 \u0927\u0941\u0935\u093e\u092f\u091a\u093e \u0928\u093e\u0939\u0940- \u0905\u0902\u0917\u0923\u093e\u0924 \u090f\u0915\u093e \u0916\u093e\u0938 \u0916\u0921\u094d\u0921\u094d\u092f\u093e\u0924\u091a \u0939\u093e\u0924 \u0927\u0941\u0935\u093e\u092f\u091a\u0947! '\u0938\u092e\u0941\u0926\u094d\u0930' \u092e\u094d\u0939\u0923\u0924\u093e\u0924 \u0924\u094d\u092f\u093e\u0932\u093e. \u0928\u0902\u0924\u0930 \u0924\u094b \u0916\u0921\u094d\u0921\u093e \u092c\u0941\u091c\u0935\u093e\u092f\u091a\u093e! \u0939\u0933\u0926\u0940-\u0915\u0941\u0902\u0915\u0935\u093e\u0932\u093e \u092f\u0947\u0923\u093e\u0930\u0940 \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915\u091c\u0923 \u0932\u0915\u094d\u0937\u094d\u092e\u0940\u091a\u0940 \u0916\u0923\u093e-\u0928\u093e\u0930\u0933\u093e\u0902\u091a\u0940 \u0913\u091f\u0940 \u0906\u0923\u093f \u0910\u092a\u0924\u0940\u0928\u0941\u0938\u093e\u0930 \u0927\u093e\u0928\u094d\u092f \u0918\u0947\u090a\u0928 \u092f\u0947\u0923\u093e\u0930! \u092a\u0941\u0928\u094d\u0939\u093e \u0917\u0943\u0939\u093f\u0923\u0940\u0928\u0947 \u0924\u0940 \u0938\u0917\u0933\u0940 '\u0930\u093e\u0938' \u0918\u091f\u0938\u094d\u0925\u093e\u092a\u0928\u0947\u092a\u0942\u0930\u094d\u0935\u0940 \u0918\u0930\u093e\u0924\u091a \u092a\u0948-\u092a\u093e\u0939\u0941\u0923\u094d\u092f\u093e\u0902\u0938\u093e\u0920\u0940 \u092a\u0926\u093e\u0930\u094d\u0925 \u0916\u093e\u090a \u0918\u093e\u0932\u0942\u0928\u091a \u0938\u0902\u092a\u0935\u093e\u092f\u091a\u0940. \u0909\u091a\u0932\u0942\u0928 \u0918\u0930\u093e\u092c\u093e\u0939\u0947\u0930 \u0915\u093e\u0939\u0940 \u0928\u094d\u092f\u093e\u092f\u091a\u0902 \u0928\u093e\u0939\u0940. \u0905\u0928\u0947\u0915 \u0920\u093f\u0915\u093e\u0923\u0940 \u0928\u0948\u0935\u0947\u0926\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u0935\u0947\u0933\u0940 \u0915\u0923\u0915\u0947\u091a\u0947 \u0967\u096c, \u0915\u0941\u0920\u0947 \u0969\u0968 \u0926\u093f\u0935\u0947 \u0906\u0923\u093f \u092e\u0941\u0920\u0947 \u0915\u0930\u0942\u0928 \u0915\u0947\u0933\u0940\u091a\u094d\u092f\u093e \u092a\u093e\u0928\u093e\u092d\u094b\u0935\u0924\u0940 \u0920\u0947\u0935\u093e\u092f\u091a\u0947! \u0928\u0948\u0935\u0947\u0926\u094d\u092f \u0915\u0947\u0933\u0940\u091a\u094d\u092f\u093e \u092a\u093e\u0928\u093e\u0935\u0930\u091a \u0935\u093e\u0922\u093e\u092f\u091a\u093e. \u0935\u093e\u0922\u0942\u0928 \u091d\u093e\u0932\u0902 \u0915\u0940 \u0935\u0931\u094d\u0939\u093e\u0921\u093e\u0924 \u0924\u094d\u092f\u093e \u0916\u094b\u0932\u0940\u091a\u0902 \u0926\u093e\u0930 \u0915\u093e\u0939\u0940 \u0915\u093e\u0933 \u092c\u0902\u0926 \u0920\u0947\u0935\u0924\u093e\u0924. \u0906\u0924 \u0932\u0915\u094d\u0937\u094d\u092e\u094d\u092f\u093e \u091c\u0947\u0935\u0924\u093e\u0924 \u0928\u093e! \u0926\u093e\u0930 \u0909\u0918\u0921\u0932\u0902 \u0915\u0940 \u092c\u093e\u0930\u0915\u093e\u0908\u0928\u0902 \u092a\u093e\u0928 \u092c\u0918\u093e\u092f\u091a\u0902. \u0915\u094b\u0923\u0915\u094b\u0923\u0924\u0947 \u092a\u0926\u093e\u0930\u094d\u0925 \u0909\u0937\u094d\u091f\u093e\u0935\u0932\u0947 \u0917\u0947\u0932\u0947\u0924? \u090f\u0915 \u0938\u0902\u0915\u0947\u0924 \u092e\u093e\u0924\u094d\u0930 \u0938\u0917\u0933\u0940\u0915\u0921\u0947! \u0917\u094c\u0930\u0940, \u0932\u0915\u094d\u0937\u094d\u092e\u0940 \u0918\u0930\u093e\u0924 \u0905\u0938\u0947\u092a\u0930\u094d\u092f\u0902\u0924 \u0918\u0930\u093e\u0924\u0932\u093e \u092a\u0948\u0938\u093e \u092c\u093e\u0939\u0947\u0930 \u0926\u094d\u092f\u093e\u092f\u091a\u093e \u0928\u093e\u0939\u0940.",(0,n.jsx)(t.br,{}),"\n",(0,n.jsx)("span",{class:"index-text",children:" gauri pujan day 2 , gauri pujan"})]})]})}function c(a={}){const{wrapper:t}={...(0,s.R)(),...a.components};return t?(0,n.jsx)(t,{...a,children:(0,n.jsx)(l,{...a})}):l(a)}},28453(a,t,e){e.d(t,{R:()=>i,x:()=>o});var r=e(96540);const n={},s=r.createContext(n);function i(a){const t=r.useContext(s);return r.useMemo(function(){return"function"==typeof a?a(t):{...t,...a}},[t,a])}function o(a){let t;return t=a.disableParentContext?"function"==typeof a.components?a.components(n):a.components||n:i(a.components),r.createElement(s.Provider,{value:t},a.children)}}}]);
